def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for agent_id in opponents_status:
        opp = opponents_status[agent_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= budget * 0.9:
                prev = opp.get('previous_trace', {})
                if prev and prev.get('bid') is not None and prev.get('bid') >= DAILY_SALARY * 0.9:
                    rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid'))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        emergency = max(DAILY_SALARY * 1.05, highest_prev + 4.0)
        if tight_supply:
            emergency += 8.0
        return float(min(budget, emergency))

    if hp <= 4 or no_water_days >= 1:
        urgent = max(DAILY_SALARY * 0.82, highest_prev + 2.5)
        if tight_supply:
            urgent += 6.0
        return float(min(budget, urgent))

    if tight_supply:
        if highest_prev >= DAILY_SALARY * 1.15 or rich_aggressive >= 2:
            bid = DAILY_SALARY * 0.22
        else:
            bid = max(DAILY_SALARY * 0.48, avg_prev * 0.72)
        return float(min(budget, bid))

    if ample_supply:
        if desperate_count >= 2:
            bid = max(DAILY_SALARY * 0.52, avg_prev * 0.85)
        else:
            bid = max(DAILY_SALARY * 0.44, avg_prev * 0.7)
        return float(min(budget, bid))

    bid = max(DAILY_SALARY * 0.5, avg_prev * 0.78)
    if highest_prev >= DAILY_SALARY * 1.0:
        bid = max(bid, highest_prev - 10.0)
    if desperate_count >= 2:
        bid += 4.0
    if day >= 8 and hp >= 6:
        bid *= 0.92

    return float(min(budget, bid))

