def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = int(day_context['supply'])  # ensure integer
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = my_status['budget']
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Estimate opponent bids from previous_trace
    estimated_bids = []
    for o in alive_opponents.values():
        prev = o.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            estimated_bids.append(prev['bid'])
        else:
            # default guess: assume they bid around half salary if no trace
            estimated_bids.append(DAILY_SALARY * 0.5)

    if estimated_bids:
        highest_est = max(estimated_bids)
    else:
        highest_est = DAILY_SALARY * 0.5

    # Base strategy
    if hp <= 2 or no_water_days >= 1:
        # desperate: bid enough to win with margin
        target = max(highest_est + 1, DAILY_SALARY * 0.9)
        return min(budget, target)

    if supply < 18:
        # low supply, need to secure water
        target = max(highest_est + 0.5, DAILY_SALARY * 0.8)
        return min(budget, target)

    if day <= 3:
        # early game, conserve
        target = min(DAILY_SALARY * 0.4, highest_est * 0.7)
        return min(budget, target)

    # late game: moderate but ensure survival
    if hp <= 4:
        target = max(highest_est - 2, DAILY_SALARY * 0.5)
        return min(budget, target)

    # healthy and supply ok: lowball
    return min(budget, DAILY_SALARY * 0.35)
